    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    # Each 2 launches four straight rays. At each row/column, the 8 cells are
    # wall segments; the incoming rays paint the opening between segments and
    # continue along openings at the next obstacle row/column.
    for sr, sc in seeds:
        # Vertical rays follow the 8 pattern's vertical opening columns.
        for dc in (-1, 1):
            c = sc + dc
            while 0 <= c < w and grid[sr][c] == 0:
                out[sr][c] = 2
                c += dc
        for dr in (-1, 1):
            r = sr + dr
            while 0 <= r < h and grid[r][sc] == 0:
                out[r][sc] = 2
                r += dr

        # Continue through successive apertures by connecting the 2-filled
        # row/column to every gap in the next encountered 8-barrier line.
        for step in (-1, 1):
            r = sr + step
            while 0 <= r < h:
                if any(v == 8 for v in grid[r]):
                    gaps = [c for c, v in enumerate(grid[r]) if v == 0]
                    if gaps:
                        lo, hi = min(gaps), max(gaps)
                        for c in range(lo, hi + 1):
                            if grid[r][c] == 0:
                                out[r][c] = 2
                        for c in gaps:
                            rr = r + step
                            while 0 <= rr < h and grid[rr][c] == 0:
                                out[rr][c] = 2
                                rr += step
                    break
                r += step
    return out
