    # The 8-pattern forms horizontal barriers. The 2 signal travels through
    # the openings, marking the passages and the connecting beam spans.
    for i, r in enumerate(walls):
        holes = gaps[r]
        for c in holes:
            out[r][c] = 2
        if not holes:
            continue
        # Horizontal beam just before each barrier spans its open apertures.
        if r > 0:
            if len(holes) == 1 and i > 0:
                # A single remaining aperture focuses the beam across the row.
                for c in range(w):
                    if grid[r - 1][c] == 0:
                        out[r - 1][c] = 2
            else:
                lo, hi = min(holes), max(holes)
                for c in range(lo, hi + 1):
                    if grid[r - 1][c] == 0:
                        out[r - 1][c] = 2
        # Rays through the openings continue vertically until the next barrier.
        end = walls[i + 1] if i + 1 < len(walls) else h
        for c in holes:
            for rr in range(r + 1, end):
                if grid[rr][c] == 0:
                    out[rr][c] = 2

