    # 2 follows a path through the holes in the repeated 8-pattern.
    for i, r in enumerate(walls):
        holes = gaps[r]
        if not holes:
            continue
        # The active segment on a wall is the interval between outermost holes.
        for c in range(min(holes), max(holes) + 1):
            if grid[r][c] == 0:
                out[r][c] = 2
        # Rays through each hole extend until the next wall.
        stop = walls[i + 1] if i + 1 < len(walls) else h
        for c in holes:
            for rr in range(r + 1, stop):
                if grid[rr][c] == 0:
                    out[rr][c] = 2
        # The signal switches between openings by drawing a bridge across the
        # blank row immediately preceding the wall when adjacent gaps differ.
        if i > 0:
            prev = gaps[walls[i - 1]]
            if prev and holes and set(prev) != set(holes):
                bridge = r - 1
                lo, hi = min(min(prev), min(holes)), max(max(prev), max(holes))
                for c in range(lo, hi + 1):
                    if grid[bridge][c] == 0:
                        out[bridge][c] = 2

