    if marker and walls:
        mr, mc = marker
        first = walls[0]
        if mr < first and gaps[first]:
            opening = min(gaps[first], key=lambda c: abs(c - mc))
            for rr in range(mr + 1, first):
                if grid[rr][mc] == 0:
                    out[rr][mc] = 2
            for c in range(min(mc, opening), max(mc, opening) + 1):
                if grid[first - 1][c] == 0:
                    out[first - 1][c] = 2
    return out
