def transform(grid):
    """Trace a 2-ray around the ends of encountered 8-stripes."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = deque()

    # The boundary marker launches a ray inward, perpendicular to its edge.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if r == 0:
                rays.append((r, c, 1, 0))
            elif r == h - 1:
                rays.append((r, c, -1, 0))
            elif c == 0:
                rays.append((r, c, 0, 1))
            elif c == w - 1:
                rays.append((r, c, 0, -1))

    visited = set()
    while rays:
        r, c, dr, dc = rays.popleft()
        ray_key = (r, c, dr, dc)
        if ray_key in visited:
            continue
        visited.add(ray_key)

        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] == 8:
                # Locate the complete contiguous stripe segment perpendicular
                # to the incoming ray.
                if dr:
                    lo = hi = c
                    while lo > 0 and grid[r][lo - 1] == 8:
                        lo -= 1
                    while hi + 1 < w and grid[r][hi + 1] == 8:
                        hi += 1
                    side_r = r - dr
                    if 0 <= side_r < h:
                        a, b = max(0, lo - 1), min(w - 1, hi + 1)
                        for x in range(a, b + 1):
                            if grid[side_r][x] == 0:
                                out[side_r][x] = 2
                        # Continue the original direction around both ends.
                        for x in (a, b):
                            if grid[side_r][x] == 0:
                                rays.append((side_r, x, dr, dc))
                else:
                    lo = hi = r
                    while lo > 0 and grid[lo - 1][c] == 8:
                        lo -= 1
                    while hi + 1 < h and grid[hi + 1][c] == 8:
                        hi += 1
                    side_c = c - dc
                    if 0 <= side_c < w:
                        a, b = max(0, lo - 1), min(h - 1, hi + 1)
                        for x in range(a, b + 1):
                            if grid[x][side_c] == 0:
                                out[x][side_c] = 2
                        for x in (a, b):
                            if grid[x][side_c] == 0:
                                rays.append((x, side_c, dr, dc))
                break
            if grid[r][c] == 0:
                out[r][c] = 2
            r += dr
            c += dc
    return out
