 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next(( (r, c) for r in range(h) for c in range(w) if grid[r][c] == 2), None)
    if marker is None:
        return out
    mr, mc = marker
    walls = [r for r, row in enumerate(grid) if sum(v == 8 for v in row) > w // 2]
    gaps = {r: [c for c, v in enumerate(grid[r]) if v == 0] for r in walls}

    # The marker's column feeds the first aperture; at each wall, signal
    # branches to every opening. Between wall rows, each active opening gives
    # a vertical ray. The horizontal connector spans the openings where the
    # incoming and outgoing tracks change position.
    if walls:
        first = walls[0]
        if mr < first:
            for rr in range(mr + 1, first):
                if grid[rr][mc] == 0:
                    out[rr][mc] = 2
            for c in gaps[first]:
                out[first][c] = 2
            # input track is joined to the aperture along the preceding row
            if first > 0:
                target = min(gaps[first], key=lambda c: abs(c-mc))
                for c in range(min(mc,target), max(mc,target)+1):
                    if grid[first-1][c] == 0: out[first-1][c] = 2

        for i, r in enumerate(walls):
            active = gaps[r]
            if i + 1 < len(walls):
                nr = walls[i+1]
                next_active = gaps[nr]
                # Every aperture is traced vertically to the next wall.
                for c in active:
                    for rr in range(r+1, nr):
                        if grid[rr][c] == 0: out[rr][c] = 2
                # Each interval between consecutive active tracks is a bridge
                # immediately above the next wall.
                if active and next_active:
                    lo, hi = min(min(active), min(next_active)), max(max(active), max(next_active))
                    for c in range(lo, hi+1):
                        if grid[nr-1][c] == 0: out[nr-1][c] = 2
                    for c in next_active: out[nr][c] = 2
            else:
                # Final apertures continue as vertical rays to the bottom edge.
                for c in active:
                    for rr in range(r+1, h):
                        if grid[rr][c] == 0: out[rr][c] = 2
    return out
